"""Per-card interceptor verification for custom/fae_but_mid (regenerated by /test-interceptors).

Validates that every fae_but_mid card carrying ``setup_interceptors`` (151 of
412 cards; the other 261 are honest vanilla) actually EMITS the effect its
printed rules TEXT claims. EXPECTED is derived from TEXT, never from what the
code emits — a "deal 3 damage" card must emit DAMAGE, not a generic
SCRY/SURVEIL/LIFE_CHANGE info-pulse.

Each test fires the card's OWN canonical trigger:
  ETB -> battlefield; death -> kill it; attack -> declare it; damage -> deal
  combat damage; upkeep/end-step -> PHASE_START for that step; spell-cast ->
  cast a spell; static/lord -> place a relevant creature and read the
  src.engine.queries delta (get_power / has_ability), not a raw QUERY event.

Plumbing events (ZONE_CHANGE, PHASE_START, QUERY_*, OBJECT_CREATED markers,
TRIGGERED_ABILITY_PUT_ON_STACK, TARGET_REQUIRED, ...) are excluded from the
event set so "some event fired" can never satisfy a content assertion.

Run:
    HYPERDRAFT_STRICT=1 HYPERDRAFT_STRICT_STACK=1 PYTHONPATH=. python tests/test_fae_but_mid_interceptors.py

Under HYPERDRAFT_STRICT, swallowed card-side errors (NameError/AttributeError in
a setup or effect_fn) surface as ERRORS instead of silent passes.
"""
import os
import sys
import traceback
from pathlib import Path

_REPO_ROOT = Path(__file__).resolve().parents[1]
if str(_REPO_ROOT) not in sys.path:
    sys.path.insert(0, str(_REPO_ROOT))

os.environ.setdefault("HYPERDRAFT_STRICT", "1")
os.environ.setdefault("HYPERDRAFT_STRICT_STACK", "1")

from src.engine import (
    Game, Event, EventType, ZoneType, CardType, Color, Characteristics,
)
from src.engine.queries import get_power, get_toughness, has_ability
from src.cards.custom.fae_but_mid import FAE_BUT_MID_CARDS


# Plumbing / structural events that must never satisfy a content assertion.
_PLUMBING = {
    "ZONE_CHANGE", "PHASE_START", "PHASE_END", "PHASE_CHANGE", "PRIORITY",
    "PRIORITY_PASS", "TURN_START", "TURN_END", "DRAW_FOR_TURN",
    "QUERY_POWER", "QUERY_TOUGHNESS", "QUERY_ABILITIES", "QUERY_TYPES",
    "QUERY_SUBTYPES", "QUERY_COLORS", "QUERY_COST",
    # NB: UNTAP is intentionally NOT plumbing — our scaffold never runs an
    # untap step, so a per-object UNTAP in the log is a card effect ("untap
    # target/all Merfolk"). (Verified: ETB + end_step phase logs no stray UNTAP.)
    "TRIGGERED_ABILITY_PUT_ON_STACK", "TARGET_REQUIRED", "TARGET_CHOSEN",
    # NB: OBJECT_CREATED is intentionally NOT plumbing here — our scaffold
    # creates the tested permanent directly and only emits ZONE_CHANGE for it,
    # so a base placement never logs OBJECT_CREATED. When it DOES appear it is a
    # token the card's effect made (the legacy create-token event path), i.e.
    # genuine content. (Verified: a vanilla ETB logs only DRAW/ZONE_CHANGE.)
    # Engine-wide telemetry markers fired by global trackers (not card effects):
    # the Void tracker emits VOID_ACTIVATED on any permanent death / MV>=5 cast,
    # so it must never satisfy a card's content assertion.
    "VOID_ACTIVATED", "VOID_TRIGGERED", "CRIME_COMMITTED", "REPLACEMENT_FIRED",
    "DELAYED_TRIGGER",
    # Stimulus events we EMIT to fire a trigger (attack/block/spell-cast). No
    # fae_but_mid card emits these as an effect, so excluding them keeps the
    # observed set to the card's actual output. (DAMAGE/TAP/UNTAP are NOT here:
    # those are legitimate card effects for some ETB/tap cards.)
    "ATTACK_DECLARED", "BLOCK_DECLARED", "SPELL_CAST", "CAST",
}


def _content_events(game):
    """Event-log type names minus pure plumbing."""
    return {e.type.name for e in game.state.event_log} - _PLUMBING


def _assert_emits(game, expected, card_name):
    got = _content_events(game)
    if not any(t in got for t in expected):
        raise AssertionError(
            f"{card_name}: expected one of {sorted(expected)} in event_log, "
            f"got {sorted(got)}"
        )


def create_creature_on_battlefield(game, player, card_name):
    """Create the card in HAND (without card_def, so interceptors don't register
    early), then move it to the battlefield via a ZONE_CHANGE event so its
    setup_interceptors register exactly once and any ETB trigger fires."""
    card_def = FAE_BUT_MID_CARDS[card_name]
    creature = game.create_object(
        name=card_name,
        owner_id=player.id,
        zone=ZoneType.HAND,
        characteristics=card_def.characteristics,
        card_def=None,
    )
    creature.card_def = card_def
    game.emit(Event(
        type=EventType.ZONE_CHANGE,
        payload={
            "object_id": creature.id,
            "from_zone": f"hand_{player.id}",
            "to_zone": "battlefield",
            "to_zone_type": ZoneType.BATTLEFIELD,
        },
    ))
    return creature


def _spawn(game, player, *, subtypes=None, types=None, power=1, toughness=1,
           colors=None, tapped=False, counters=None, name="Test Creature"):
    """Spawn a plain vanilla support creature on the battlefield."""
    ch = Characteristics(
        types=set(types) if types else {CardType.CREATURE},
        subtypes=set(subtypes) if subtypes else set(),
        power=power,
        toughness=toughness,
        colors=set(colors) if colors else set(),
    )
    obj = game.create_object(
        name=name, owner_id=player.id, zone=ZoneType.HAND,
        characteristics=ch, card_def=None,
    )
    game.emit(Event(
        type=EventType.ZONE_CHANGE,
        payload={
            "object_id": obj.id,
            "from_zone": f"hand_{player.id}",
            "to_zone": "battlefield",
            "to_zone_type": ZoneType.BATTLEFIELD,
        },
    ))
    if tapped:
        obj.state.tapped = True
    if counters:
        for ct, n in counters.items():
            obj.state.counters[ct] = obj.state.counters.get(ct, 0) + n
    return obj


def _new_game():
    game = Game()
    p1 = game.add_player("Alice")
    p2 = game.add_player("Bob")
    return game, p1, p2


