def test_card_changeling_wayfinder():
    """Changeling Wayfinder: Changeling. When this creature enters, you may search your library for a basic land card, reveal it, put it into your hand, then shuffle."""
    game, p1, p2 = _new_game()
    obj = create_creature_on_battlefield(game, p1, "Changeling Wayfinder")
    _assert_emits(game, ['SEARCH_LIBRARY', 'LIBRARY_SEARCH', 'LIBSEARCH_BEGIN'], "Changeling Wayfinder")

def test_card_rooftop_percher():
    """Rooftop Percher: Changeling. Flying. When this creature enters, exile up to two target cards from graveyards. You gain 3 life."""
    game, p1, p2 = _new_game()
    obj = create_creature_on_battlefield(game, p1, "Rooftop Percher")
    _assert_emits(game, ['LIFE_CHANGE', 'LIFE_GAIN', 'LIFE_LOSS', 'EXILE'], "Rooftop Percher")

def test_card_adept_watershaper():
    """Adept Watershaper: Other tapped creatures you control have indestructible."""
    game, p1, p2 = _new_game()
    create_creature_on_battlefield(game, p1, "Adept Watershaper")
    ally = _spawn(game, p1, subtypes=[], tapped=True, name='Granted Ally')
    assert has_ability(ally, "indestructible", game.state), (
        f"Adept Watershaper: should grant indestructible to a creature you control")

