def test_card_eirdu_carrier_of_dawn():
    """Eirdu, Carrier of Dawn: Flying, lifelink. Creature spells you cast have convoke. At the beginning of your first main phase, you may pay {B}. If you do, transform Eirdu."""
    game, p1, p2 = _new_game()
    obj = create_creature_on_battlefield(game, p1, "Eirdu, Carrier of Dawn")
    # Deal combat damage from this creature to the opponent player.
    game.emit(Event(type=EventType.DAMAGE, payload={'source': obj.id, 'target': p2.id,
        'amount': max(1, obj.characteristics.power or 1), 'is_combat': True,
        'target_type': 'player'}, source=obj.id))
    _assert_emits(game, ['LIFE_CHANGE', 'LIFE_GAIN', 'LIFE_LOSS'], "Eirdu, Carrier of Dawn")

